s=s[:a]+''' // Two product films with one clear narrative each. Timelines pause outside the viewport.
 document.querySelectorAll('[data-service-film]').forEach(film=>{if(!M)return;const monthly=film.dataset.serviceFilm==='monthly';if(monthly){const base=new Date(),months=Array.from({length:3},(_,i)=>new Date(base.getFullYear(),base.getMonth()+i,1).toLocaleDateString('tr-TR',{month:'long'}));film.querySelectorAll('.sf-month-tabs>span').forEach((el,i)=>el.textContent=months[i]);film._scene=M.create(film,{duration:24000,staticAt:12000,render:t=>{const month=Math.min(2,Math.floor(t/8)),local=t%8,names=[['Moda Kahve','Ada Kuaför'],['Park Fırın','Form Pilates'],['Ege Dental','Köşe Mutfak']][month];film.querySelectorAll('.sf-month-tabs>span').forEach((el,i)=>el.classList.toggle('active',month===i));film.querySelectorAll('.sf-new-pins>.sf-pin').forEach((pin,i)=>{const a=M.ease((local-.5-i*.6)/.65);pin.style.opacity=String(a);pin.style.transform='translateY('+((1-a)*10)+'px) scale('+(.82+.18*a)+')';pin.style.left=([13,24,17][month]+i*12)+'%';pin.style.top=([40,36,43][month]+i*23)+'%'});film.querySelectorAll('.sf-new-record').forEach((row,i)=>{row.querySelector('span').textContent=names[i];const a=M.ease((local-2-i*.15)/.6);row.style.opacity=String(.12+.88*a);row.style.transform='translateY('+((1-a)*5)+'px)'});film.querySelector('.sf-month-map').style.backgroundPosition=(48+month*5)+'% 50%'}})}else{film._scene=M.create(film,{duration:16000,staticAt:10000,render:t=>{const area=M.ease((t-.3)/1.2),result=M.ease((t-5.3)/.8)*(1-M.smooth((t-14.5)/1));film.querySelector('.sf-area path').style.strokeDashoffset=String(1-area);film.querySelector('.sf-area').style.opacity=String((.25+.75*area)*(1-result*.8));film.querySelectorAll('.sf-pins>.sf-pin').forEach((pin,i)=>{const a=M.ease((t-1.2-i*.5)/.6);pin.style.opacity=String(a*(1-result*.6));pin.style.transform='translateY('+((1-a)*10)+'px) scale('+(.82+.18*a)+')'});film.querySelector('.sf-result').style.opacity=String(result);film.querySelector('.sf-result').style.transform='translateY('+((1-result)*12)+'px)';film.querySelector('.sf-query').style.opacity=String(1-result);film.querySelector('.sf-scan').style.transform='translateX('+(-100+M.smooth((t-2.5)/2.4)*650)+'%)';film.querySelector('.sf-scan').style.opacity=String(t>2.5&&t<5?.55:0)}})}});
'''+s[b:];p.write_text(s,encoding='utf-8')
